def cost_of(a):
    a, c = list(a), 0
    for i in range(1, len(a)):
        key, j = a[i], i - 1
        while j >= 0:
            c += 1
            if a[j] > key:
                a[j + 1] = a[j]; j -= 1
            else:
                break
        a[j + 1] = key
    return c
arr = [6, 2, 9, 5, 5, 8, 1]
inv = sum(arr[i] > arr[k] for i in range(7) for k in range(i + 1, 7))
print(cost_of(arr), inv)                            # 16 12
assert cost_of(arr) == 16 and inv == 12

import sqlite3
con = sqlite3.connect(":memory:"); con.isolation_level = None
con.execute("PRAGMA foreign_keys = ON")
# SQLite (unlike standard SQL) lets PRIMARY KEY columns hold NULL, so NOT NULL is added to mimic the standard.
con.executescript("""
CREATE TABLE Course (cid CHAR(4) PRIMARY KEY, title VARCHAR(30) UNIQUE);
CREATE TABLE Section (sid INT NOT NULL PRIMARY KEY, cid CHAR(4) REFERENCES Course(cid) ON DELETE CASCADE,
  room VARCHAR(5), cap INT CHECK (cap BETWEEN 10 AND 60), UNIQUE (cid, room));
CREATE TABLE Enroll (sid INT NOT NULL REFERENCES Section(sid) ON DELETE CASCADE, stu INT NOT NULL,
  grade CHAR(1), PRIMARY KEY (sid, stu));
INSERT INTO Course VALUES ('C101','Databases'),('C102','Algorithms');
INSERT INTO Section VALUES (1,'C101','R1',40),(2,'C101','R2',30),(3,'C102','R1',50);
INSERT INTO Enroll VALUES (1,501,'A'),(1,502,'B'),(2,501,'C'),(3,503,'A');""")
S = ["INSERT INTO Section VALUES (4,'C102','R1',20)", "INSERT INTO Section VALUES (5,NULL,NULL,NULL)",
     "INSERT INTO Section VALUES (6,'C103','R3',25)", "INSERT INTO Enroll VALUES (2,NULL,'B')",
     "DELETE FROM Course WHERE cid='C101'", "UPDATE Section SET cap=5 WHERE sid=3"]
rej = []
for i, s in enumerate(S, 1):
    try: con.execute(s)
    except sqlite3.Error as e: rej.append(f"S{i}")
print(rej)                                                      # ['S1', 'S3', 'S4', 'S6']
print(con.execute("SELECT * FROM Section").fetchall(), con.execute("SELECT * FROM Enroll").fetchall())
assert rej == ["S1", "S3", "S4", "S6"]
