import networkx as nx
E = [(1,2),(1,3),(1,5),(2,3),(2,4),(2,5),(3,4),(3,6),(4,6)]
G = nx.Graph(E)
odd = sorted(v for v, d in G.degree() if d % 2)
print(dict(G.degree()), nx.is_connected(G), odd)                 # odd = [1, 4]
# brute force: every (start, end) pair that some Euler trail realises
ends = set()
def dfs(cur, used, start):
    if len(used) == len(E): ends.add(frozenset((start, cur))); return
    for i, (a, b) in enumerate(E):
        if i not in used and cur in (a, b): dfs(b if cur == a else a, used | {i}, start)
for s in G: dfs(s, frozenset(), s)
print(ends)                                                      # {frozenset({1, 4})}
assert ends == {frozenset((1, 4))}
